    // Compute the current doctor/date's slot length (MinPerCase) as a "00:MM" FullCalendar
    // duration string. Falls back to 15 minutes when no schedule has been fetched yet.
    function getCurrentSlotDurationStr() {
        var mins = parseInt($scope.allUserAvailabilitySlots && $scope.allUserAvailabilitySlots.MinPerCase) ||
            parseInt($scope.selectedAppointmentObject && $scope.selectedAppointmentObject.DocObj && $scope.selectedAppointmentObject.DocObj.MinPerCase) || 15;
        return "00:" + (mins < 10 ? "0" + mins : mins);
    }

    // Push the current MinPerCase into the live FullCalendar instance's grid, if one already
    // exists. A per-view "views.resourceTimeGridDay.slotDuration" override (set at calendar
    // creation time below) takes precedence over a plain top-level setOption('slotDuration', ...),
    // so update both the top-level option and the view-specific override (merging with whatever
    // else is already on that view's config) to make sure the change actually takes effect.
    function applyLiveSlotDuration() {
        if (!calendar) {
            return;
        }
        var newSlotDuration = getCurrentSlotDurationStr();
        try {
            var currentViews = calendar.getOption('views') || {};
            var mergedViews = angular.extend({}, currentViews);
            mergedViews.resourceTimeGridDay = angular.extend({}, currentViews.resourceTimeGridDay, {
                slotDuration: newSlotDuration
            });
            calendar.setOption('views', mergedViews);
            calendar.setOption('slotDuration', newSlotDuration);
        } catch (e) {
            console.log("applyLiveSlotDuration failed:", e);
        }
    }

