    $scope.getAllSurgeriesList = function () {

        var HospitalIdParam = $scope.ParentHospitalId;
        $scope.GetAllIndicator = 1;
        if ($scope.surgeryListGetObj.HospitalObj.ClinicId !== 0) {
            HospitalIdParam = $scope.surgeryListGetObj.HospitalObj.ClinicId;
            $scope.GetAllIndicator = 0;
        }
        var DoctorIdParam = $scope.surgeryListGetObj.DoctorObj.DoctorID;
        var CounselorIdParam = 0;
        if ($scope.surgeryListGetObj.CounselorObj) {
            CounselorIdParam = $scope.surgeryListGetObj.CounselorObj.DoctorID;
        }
        var StartDateParam = $filter("date")(new Date($scope.surgeryListGetObj.FromDate), "yyyy-MM-dd");
        var EndDateParam = $filter("date")(new Date($scope.surgeryListGetObj.ToDate), "yyyy-MM-dd");
        var SurgeryStatusParam = parseInt($scope.surgeryListGetObj.Status);
        var SearchTextParam = $scope.surgeryListGetObj.SearchText;
        var CounselorstatusId = parseInt($scope.surgeryListGetObj.CounselorStatusId);
        var params = {
            "HospitalID": HospitalIdParam,
            "DoctorId": DoctorIdParam,
            "CounselorId": CounselorIdParam,
            "StartDate": StartDateParam,
            "EndDate": EndDateParam,
            "PageSize": $scope.SurgeryListPageSize,
            "PageNo": $scope.SurgeryListPageNo,
            "GetAllIndicator": $scope.GetAllIndicator,
            "SurgeryStatusInd": $scope.SurgeryStatusInd,
            "CounselorStatusId": CounselorstatusId,
            "SearchText": $scope.surgeryListGetObj.firstname,
            "SearchPatientDisplayId": $scope.surgeryListGetObj.PatientDisplayId,
            "OldPatientMRNO": $scope.surgeryListGetObj.OldPatientDisplayId
        };

        eHnotePatientDataService.GetAllSurgeriesList(params, OnGetSurgeriesListSuccess, OnGetSurgeriesListError);



    };
    function OnGetSurgeriesListSuccess(data) {


        $scope.TotalAdmittedCount = data.TotalAdmittedCount;
        $scope.TotalAppointmentCount = data.TotalAppointmentCount;
        $scope.TotalDischargedCount = data.TotalDischargedCount;
        $scope.TotalSurgeriesCount = data.TotalSurgeriesCount;
        $scope.AdvicedCount = data.AdvicedCount;
        $scope.AcceptedCount = data.AcceptedCount || 0;
        $scope.FollowUpCount = data.FollowUpCount || 0;


        if ($scope.SurgeryStatusInd === "All") {
            $scope.TotalCount = $scope.TotalSurgeriesCount;
        }
        if ($scope.SurgeryStatusInd === 9) {
            $scope.TotalCount = $scope.TotalAppointmentCount;
        }
        if ($scope.SurgeryStatusInd === 7) {
            $scope.TotalCount = $scope.TotalAdmittedCount;
        }
        if ($scope.SurgeryStatusInd === 8) {
            $scope.TotalCount = $scope.TotalDischargedCount;
        }
        if ($scope.SurgeryStatusInd === 1) {
            $scope.TotalCount = $scope.AdvicedCount;
        }
        if ($scope.SurgeryStatusInd === 6) {
            $scope.TotalCount = $scope.FollowUpCount;
        }
        if ($scope.SurgeryStatusInd === 2) {
            $scope.TotalCount = $scope.AcceptedCount;
        }

        if (data.rows.length > 0) {
            $scope.SurgeriesListArray = [];

            if ($scope.SurgeryStatusInd === 1 || $scope.SurgeryStatusInd === 7 || $scope.SurgeryStatusInd === 8) {
                $scope.SurgeriesListArray = data.rows;
                angular.forEach($scope.SurgeriesListArray, function (item) {
                    var array_list = ['#af77c6', '#e4c120', '#69b3e7', '#ed9945', '#90c752'];
                    var value = array_list[Math.floor(Math.random() * array_list.length)];
                    item.PatientShortName = item.PatientName.substring(0, 2);
                    item.colors = value;
                })
            } else {
                angular.forEach(data.rows, function (item) {
                    var array_list = ['#af77c6', '#e4c120', '#69b3e7', '#ed9945', '#90c752'];
                    var value = array_list[Math.floor(Math.random() * array_list.length)];

                    var obj = {
                        "PatientId": item.Patient.PatientId,
                        "PatientDisplayId": item.Patient.PatientDisplayId,
                        "PatientEmailId": item.Patient.PatientEmailId,
                        "S3URL": item.Patient.S3URL || "",
                        "DOB": item.Patient.DOB,
                        "PatientName": item.Patient.PatientName,
                        "Sex": item.Patient.Sex ? item.Patient.Sex : item.Patient.Gender,
                        "MobileNo": item.Patient.MobileNo,
                        "ContactNo": item.Patient.ContactNo,
                        "colors": value,
                        "PatientShortName": item.Patient.PatientName.substring(0, 2),
                        "AdmissionId": item.AdmissionId || 0,
                        "SurgeryStatusInd": $scope.SurgeryStatusInd,
                        "AdmissionDate": item.AdmissionDate || "",
                        "AdmissionNumber": item.AdmissionNumber || "",
                        "AdmissionStatusId": item.AdmissionStatusId || "",
                        "AgeInYears": item.Patient.AgeInYears,
                        "AgeInMonths": item.Patient.AgeInMonths,
                        "AgeInDays": item.Patient.AgeInDays,
                        "SurgeryDetails": [],
                        "PatientTypeName": item.Patient.PatientTypeName,
                        "IsVIPInd": item.Patient.IsVIPInd,
                        "IsHighRiskInd": item.Patient.IsHighRiskInd
                    }
                    obj.SurgeryDetails.push(item);
                    $scope.SurgeriesListArray.push(obj);
                })
            }



            angular.forEach($scope.SurgeriesListArray, function (item) {
                item.SurgeryDetails = item.SurgeryDetails || [];
                if (item.SurgeryDetails.length > 0) {
                    angular.forEach(item.SurgeryDetails, function (subitem, subindex) {
                        subitem.OrgSurgeryBillingId = parseInt(subitem.OrgSurgeryBillingId) || 0;
                        subitem.SurgeryBillingObject = null;
                        if (subitem.OrgSurgeryBillingId !== 0) {
                            subitem.SurgeryBillingObject = {
                                "OrgSurgeryBillingId": subitem.OrgSurgeryBillingId,
                                "SurgeryBillingName": subitem.SurgeryBillingName,
                                "SurgeryCost": subitem.SurgerBillingCost,
                                "OrganizationSurgeryId": subitem.OrganizationSurgeryId,
                                "SurgeryName": subitem.SurgeryName
                            };
                        }
                    });
                }
            });


            $scope.SelectedSurgery = $scope.SurgeriesListArray[0];

            $scope.isFinalSettlementBillingDone.value = $scope.SelectedSurgery.IsFinalSettlementDone;

            $scope.SelectedSurgery.SurgeryStatusInd = $scope.SurgeryStatusInd;



            $scope.SelectedSurgery.AllDoctorsList = $scope.cacheStorageItem.AllDoctorsList;
            datapersistanceFactory.set("SelectedSurgery", $scope.SelectedSurgery);

        } else {
            $scope.SurgeriesListArray = [];
            //$scope.SelectedSurgery = "";
        }
    }
