    $scope.GetASCAppointmentDetailsById = function () {

        let PatientSurgeryId = null;
        if ($scope.cacheStorageItem.AppointmentTypeId == 7) {
            if ($scope.cacheStorageItem.PreAdmSurgeryList.length > 0) {
                PatientSurgeryId = $scope.cacheStorageItem.PreAdmSurgeryList[0].PatientSurgeryId;
            }
        } else if ($scope.cacheStorageItem.AppointmentTypeId == 4 || $scope.cacheStorageItem.AppointmentTypeId == 14) {
            if ($scope.cacheStorageItem.SurgeryList.length > 0) {
                PatientSurgeryId = $scope.cacheStorageItem.SurgeryList[0].PatientSurgeryId;
            }
        }

        var params = {
            "AppointmentId": $scope.mainobj.AppointmentId || null,
            "AppointmentTypeId": $scope.selectedApptObj.AppointmentTypeId,
            "PatientSurgeryId": PatientSurgeryId || null
        };
        eHnotePatientDataService.GetASCAppointmentDetailsById(params).then(function (resp) {
            if (resp.data.status == "Success") {
                $scope.mainobj.Patientlist = [];
                $scope.mainobj.Patientlist = resp.data.rows || [];
                if (resp.data.rows.length > 0) {
                    if (!angular.equals(resp.data.rows[0].PatientCheckIn, {})) {
                        $scope.mainobj.PatientCheckIn = resp.data.rows[0].PatientCheckIn || {};
                    }
                    if (!angular.equals(resp.data.rows[0].SurgeryStaff, {})) {
                        $scope.mainobj.SurgeryStaff = resp.data.rows[0].SurgeryStaff || {};
                    }
                    if (!angular.equals(resp.data.rows[0].CoManagement, {})) {
                        $scope.mainobj.CoManagement = resp.data.rows[0].CoManagement || {};
                    }
                    if (resp.data.rows[0].AppointmentNotes.length > 0) {
                        $scope.mainobj.AppointmentNotes = resp.data.rows[0].AppointmentNotes || [];
                    } else {
                        $scope.mainobj.AppointmentNotes = [];
                    }
                    if (resp.data.rows[0].PatientInsuranceList.length > 0) {
                        $scope.mainobj.PatientInsuranceList = resp.data.rows[0].PatientInsuranceList || [];
                    }
                    if (resp.data.rows[0].AppointmentInsuranceList.length > 0) {
                        $scope.mainobj.AppointmentInsuranceList = resp.data.rows[0].AppointmentInsuranceList || [];
                    } else {
                        $scope.mainobj.AppointmentInsuranceList = [];
                    }
                    if (!angular.equals(resp.data.rows[0].TrackerDetails, {})) {
                        $scope.mainobj.TrackerDetails = resp.data.rows[0].TrackerDetails || {};
                    }

                }
                $scope.cacheStorageItem.PreAdmAppointmentId = resp.data.rows[0].PreAdmAppointmentId;
                $scope.cacheStorageItem.AscAppointmentId = resp.data.rows[0].AscAppointmentId ;
                $scope.cacheStorageItem.AppointmentId = $scope.mainobj.AppointmentId;
                $scope.cacheStorageItem.PatientID = resp.data.rows[0].PatientID;
                $scope.cacheStorageItem.PatientCheckIn = resp.data.rows[0].PatientCheckIn || "";
                $scope.cacheStorageItem.AppointmentStatus = $scope.selectedApptObj.AppointmentStatus;
                $scope.cacheStorageItem.AppointmentDate = $scope.selectedApptObj.ConsultationDt;
                $scope.cacheStorageItem.selectedApptObj.AppointmentStatusId = resp.data.rows[0].AppointmentStatusId;
                $scope.cacheStorageItem.selectedApptObj.AdmissionId = resp.data.rows[0].AdmissionId||0;

                $scope.cacheStorageItem.PatientImageS3URL = resp.data.rows[0].S3URL || "";

                resp.data.rows[0].PatientCheckIn.AdmissionId = resp.data.rows[0].PatientCheckIn.AdmissionId || 0;
                if (resp.data.rows[0].PatientCheckIn.AdmissionId !== 0) {
                    $scope.cacheStorageItem.AdmissionId = resp.data.rows[0].PatientCheckIn.AdmissionId || 0;
                }
                console.log($scope.cacheStorageItem.AdmissionId + "__AdmissionId");
                $scope.AddToCache();

                var mobileno = eHnoteUserDataService.UsMobileFormatChange($scope.mainobj.Patientlist[0].MobileNo);
                $scope.mainobj.Patientlist[0].MobileNo = mobileno.UsFormatMobileNumber;

                $scope.selectedApptObj.CheckinStatusId = resp.data.rows[0].AppointmentStatusId || null;
                // check in check out time 
                resp.data.rows[0].WalkInTime = resp.data.rows[0].WalkInTime || "";
                var ConvertWalkInTime = $filter('date')(resp.data.rows[0].WalkInTime, "hh:mm a") || "";
                resp.data.rows[0].CheckInTime = "";
                resp.data.rows[0].CheckInTime = ConvertWalkInTime;
                var datetime = moment(resp.data.rows[0].ConsultationDt + "T" + resp.data.rows[0].StartTime);
                resp.data.rows[0].ConvertDateStartTime = datetime.format("hh:mm A") || "";
            }

        }, function (err) {

        });


    };




