    $scope.ChangeHospitalNew = function (item) {
        $scope.surgeryListGetObj.HospitalObj = item;
        $scope.selectedBranch = "";

        if (item.ClinicId === 0) {
            $scope.defaultbranch = $filter("filter")($scope.AllUserBranchesList, function (item) {
                return item.BranchId === doctorinfo.doctordata.UserAddress[0].ClinicId;
            });
            $scope.selectedBranch = $scope.defaultbranch[0];
        } else {
            $scope.selectedBranch = item;
        }



        $scope.BranchCall = "OnChange";
        GetBranchSubSpecializations($scope.selectedBranch.SubOrganizationId, $scope.selectedBranch.BranchId);

    };

    $scope.ChangeHospital = function (item) {
        $scope.surgeryListGetObj.HospitalObj = item;
        if ($scope.RoleId !== 1 && $scope.RoleId !== 56) {
            var doctorslist = [];
            if (item.ClinicId === 0) {

                angular.forEach($scope.AllUserBranchesList, function (item, index) {
                    item.Doctors = item.Doctors || [];
                    doctorslist = doctorslist.concat(item.Doctors);
                });

            } else {
                if ($scope.RoleId === 1 || $scope.RoleId === 56) {
                    doctorslist = $scope.BranchDoctorsList || [];
                } else {
                    doctorslist = item.Doctors || [];
                }

            }
            $scope.ReloadDoctors(doctorslist);
        }

    };
    $scope.ReloadDoctors = function (doctorslist) {

        var docAll = {};
        $scope.AllBranchDoctorlist = angular.copy(doctorslist);
        $scope.BranchDoctorsList = $filter("filter")($scope.AllBranchDoctorlist, function (item) {
            return item.RoleId === 1 || item.RoleId === 3 || item.RoleId === 4 || item.RoleId === 16 || item.RoleId === 43 || item.RoleId === 56 || item.RoleId === 57;
        });
        $scope.BranchDoctorsList = _.uniq($scope.BranchDoctorsList, false, function (p) {
            return p.DoctorID;
        });
        if ($scope.BranchDoctorsList.length > 0) {
            if ($scope.RoleId !== 1 && $scope.RoleId !== 56) {
                docAll = { "DoctorID": 0, "FullName": "All Doctors", "AddressID": 0, "MinPerCase": 15 };
                $scope.BranchDoctorsList.unshift(angular.copy(docAll));
            }

        } else {
            if ($scope.RoleId !== 1 && $scope.RoleId !== 56) {
                docAll = { "DoctorID": 0, "FullName": "No Docotors", "AddressID": 0, "MinPerCase": 15 };
                $scope.BranchDoctorsList.push(angular.copy(docAll));
            }

        }
        if ($scope.RoleId !== 1 && $scope.RoleId !== 56) {
            $scope.surgeryListGetObj.DoctorObj = $scope.BranchDoctorsList[0];
        }




    };
    $scope.ChangeDoctor = function (doctorobj) {
        $scope.surgeryListGetObj.DoctorObj = doctorobj;
    };
    $scope.ChangeCounsel = function (counselobj) {
        $scope.surgeryListGetObj.CounselorObj = counselobj;
    };









    $scope.SearchSurgeryList = function (val, stab) {
        //$scope.SurgeryStatusInd = "All";
        $scope.IsPatientSelected = true;
        $scope.showpatientDetails = true;
        let tab = stab || '';
        if (val === 0) {
            $scope.ASCDynamicStatusTabs.Subtab = 1;
            if (tab == '') {
                $scope.NavObj.IsApptSelectedInfoInd = false;
                $scope.cacheStorageItem.AppointmentId = 0;
            }
        } else if (val === 1) {
            $scope.ASCDynamicStatusTabs.Subtab = 2;
        } else if (val === 2) {
            $scope.ASCDynamicStatusTabs.Subtab = 3;
        } else if (val === 3) {
            $scope.ASCDynamicStatusTabs.Subtab = 4;
        }

        var checkedLocationList = [];
        if ($scope.AppListdoctoraddress.length > 0) {
            checkedLocationList = _.where($scope.AppListdoctoraddress, { IsChecked: true });
        }

        var checkedArrayList = [];
        if ($scope.MultiselectDoctorlist.length > 0) {
            checkedArrayList = _.where($scope.MultiselectDoctorlist, { isChecked: true });
        }
        var checkedVisitreasons = [];
        if ($scope.Visitreasons.length > 0) {
           /* $scope.Allvisitresons.forEach(site => site.isChecked = true);*/
            checkedVisitreasons = _.where($scope.Visitreasons, { isChecked: true });
        }
        var checkedBookingTypesArray = [];
        if ($scope.BookingTypesArray.length > 0) {
            checkedBookingTypesArray = _.where($scope.BookingTypesArray, { IsChecked: true });
        }
        var checkedAppointmentStatusArray = [];
        if ($scope.AppointmentStatusArray.length > 0) {
            checkedAppointmentStatusArray = _.where($scope.AppointmentStatusArray, { IsChecked: true });
        }
        var checkedBookedstatusFilterList = [];
        if ($scope.BookedstatusFilterList.length > 0) {
            checkedBookedstatusFilterList = _.where($scope.BookedstatusFilterList, { IsChecked: true });
        }
        var checkedProfileStatusList = [];
        if ($scope.ProfileStatusList.length > 0) {
            checkedProfileStatusList = _.where($scope.ProfileStatusList, { IsChecked: true });
        }
        var checkedPatientTagList = [];
        if ($scope.PatientTagList.length > 0) {
            checkedPatientTagList = _.where($scope.PatientTagList, { IsChecked: true });
        }
        var checkedAppointmentStatusFilterArray = [];
        if ($scope.AppointmentStatusFilterArray.length > 0) {
            checkedAppointmentStatusFilterArray = _.where($scope.AppointmentStatusFilterArray, { isChecked: true });
        }
        var cacheobj = {
            "SelectedDoctorsList": checkedArrayList||[],
            "OPFromDate": $scope.SearchObj.ConsultationDt||"",
            "PatientTagList": checkedPatientTagList||[],
            "ProfileStatusList": checkedProfileStatusList||[],
            "BookedstatusFilterList": checkedBookedstatusFilterList||[],
            "AppointmentStatusArray": checkedAppointmentStatusArray||[],
            "BookingTypesArray": checkedBookingTypesArray||[],
            "Visitreasons": checkedVisitreasons||[],
            "AppointmentStatusFilterArray": checkedAppointmentStatusFilterArray || [],
            "Subtab": $scope.ASCDynamicStatusTabs.Subtab || 0,
            "RoomTypeId": $scope.RoomTypeId || 0,
            "SelectedLocationList": checkedLocationList || [],
        };
        eHnoteMasterDataService.addSelectedPreAdminList(cacheobj);
        $scope.SurgeryListPageNo = 1;
        $scope.GetASCDynamicStatusCounts();
        $scope.GetAllAscAppointmentsList(val);
    };
