    $scope.RefreshAppointments = function () {
        if ($scope.AppListdoctoraddress && doctorInfo?.doctordata?.UserAddress?.length > 0) {
            let defaultClinicId = doctorInfo.doctordata.UserAddress[0].ClinicId;

            angular.forEach($scope.AppListdoctoraddress, function (item) {
                if (item.ClinicId === defaultClinicId) {
                    item.IsChecked = true;
                    $scope.LocationTypeObj.SelectLocationString = item.ClinicName || '';
                } else {
                    item.IsChecked = false;
                }
            });
        }
        var subSplArray = _.pluck($scope.allSubSpecializationsArray, "SubSpecializationId").join(",");
        var locationIds = $scope.AppListdoctoraddress.filter(pitem => pitem.IsChecked && pitem.ClinicId !== 0)
            .map(pitem => pitem.ClinicId)
            .join(",");

        var obj = {
            "OrganizationId": locationIds,
            "UserId": doctorinfo.doctorid,
            "VisitTypeId": 0,
            "visitReasonSearch": "",
            "PageNumber": 1,
            "PageSize": 1000,
            "IsFrequent": "N"
        };
        var obj1 = {
            "BranchId": locationIds || 0,
            "SubSpecializationIdArray": subSplArray
        };

        $q.all([
            //eHnotePatientVisitReasonServices.GetOrganizationActiveAppointmentVisitReasonsById(obj),
            eHnotePatientVisitReasonServices.GetOrganizationActiveAndInActiveApptVisitReasons(obj),
            eHnoteMainAppointmentService.getAllUsersByDepartmentIdNew(obj1)
        ]).then(function (resp) {
            if (resp[0].data !== undefined) {
                $scope.AllDoctorsObj.AllVisitReasonsCheck = false;
                if (resp[0].data.rows.length > 0) {
                    $scope.Visitreasons = resp[0].data.rows;
                    $scope.CalVisitreasons = resp[0].data.rows;
                    $scope.Visitreasons = $filter('filter')($scope.Visitreasons, { 'VisitTypeId': 7 }, true);
                    angular.forEach($scope.Visitreasons, function (item) {
                        item.isChecked = true;
                    });
                    $scope.AllDoctorsObj.AllVisitReasonsCheck = true;
                    $scope.selectedVisitReason = 'All Visit Reasons';
                } else {
                    $scope.Visitreasons = [];
                }
            }

            if (resp[1].data.rows.length > 0) {

                var UsersList = [];
                UsersList = resp[1].data.rows || [];
                localStorageFactory.set("allUserList", UsersList);
                UsersList = _.uniq(UsersList, false, function (p) { return p.DoctorID; });
                var filteredUsers = [];
                angular.forEach(UsersList, function (Aitem) {
                    if (Aitem.RoleId === 1 || Aitem.RoleId === 43) {
                        filteredUsers.push(Aitem);
                    }
                });
                $scope.MultiselectDoctorlist = [];
                $scope.Calendardoctorlist1 = [];
                if ($scope.connectedUserObj.Available) {
                    if (filteredUsers.length > 0) {
                        angular.forEach(filteredUsers, function (kitem) {
                            kitem.DoctorfullNamewithNPI = kitem.NPI + '-' + kitem.SecondUserFullName;
                            if (doctorInfo.doctordata.User[0].RoleId == 1 && $scope.connectedUserObj.Users.length > 0) {
                                var TempReasion = $filter("filter")($scope.connectedUserObj.Users, function (uitem) { return uitem.ChildUserId == kitem.DoctorID || kitem.DoctorID == doctorInfo.doctordata.User[0].DoctorID; }) || [];
                                if (TempReasion.length > 0) {
                                    $scope.MultiselectDoctorlist.push(kitem);
                                    $scope.Calendardoctorlist1.push(kitem);
                                }
                            } else if (doctorInfo.doctordata.User[0].RoleId == 1 && $scope.connectedUserObj.Users.length == 0) {
                                if (kitem.DoctorID == doctorInfo.doctordata.User[0].DoctorID) {
                                    $scope.MultiselectDoctorlist.push(kitem);
                                    $scope.Calendardoctorlist1.push(kitem);
                                }
                            } else {
                                $scope.MultiselectDoctorlist.push(kitem);
                                $scope.Calendardoctorlist1.push(kitem);
                            }
                        });
                    }
                }
                else {
                    angular.forEach(filteredUsers, function (kitem) {
                        kitem.DoctorfullNamewithNPI = kitem.NPI + '-' + kitem.SecondUserFullName;
                        $scope.MultiselectDoctorlist.push(kitem);
                        $scope.Calendardoctorlist1.push(kitem);
                    });
                }


                if ($scope.MultiselectDoctorlist.length > 0) {
                    if ($scope.connectedUserObj.Available) {
                        if (doctorInfo.doctordata.User[0].RoleId == 1) {
                            var checkedArray = _.where($scope.MultiselectDoctorlist, { isChecked: true });
                            $scope.AllDoctorsObj.AllDoctorCheck = checkedArray.length > 0 && $scope.MultiselectDoctorlist.length === checkedArray.length ? true : false;
                            if (checkedArray.length == 0) {
                                $scope.selectedDoctors = "Select Doctors";
                            } else {
                                if (checkedArray.length === 1) {
                                    $scope.selectedDoctors = checkedArray[0].SecondUserFullName + '-' + checkedArray[0].NPI;
                                } else {
                                    if ($scope.AllDoctorsObj.AllDoctorCheck) {
                                        $scope.selectedDoctors = "All";
                                    } else {
                                        $scope.selectedDoctors = "Select Doctors";
                                    }
                                }
                            }
                        } else {
                            angular.forEach($scope.MultiselectDoctorlist, function (Aitem, $index) {
                                Aitem.isChecked = false;
                                $scope.AllDoctorsObj.AllDoctorCheck = false;
                                if (Aitem.DoctorID === doctorInfo.doctordata.User[0].DoctorID) {
                                    Aitem.DoctorfullNamewithNPI = Aitem.NPI + '-' + Aitem.SecondUserFullName;
                                    Aitem.isChecked = true;
                                }
                                angular.forEach($scope.connectedUserObj.Users, function (Uitem, $index) {
                                    if (Uitem.ChildUserId == Aitem.DoctorID) {
                                        Aitem.isChecked = true;
                                    }
                                });

                            });
                            $scope.selectedDoctors = "Selected Doctors";
                        }
                    } else {
                        if ($scope.userLoginDetails.RoleID != 1 && $scope.userLoginDetails.RoleID != 43) {
                            angular.forEach($scope.MultiselectDoctorlist, function (Aitem, $index) {
                                $scope.AllDoctorsObj.AllDoctorCheck = true;
                                Aitem.isChecked = true;
                            });
                            $scope.selectedDoctors = "All";
                        }
                        else {
                            if ($scope.userLoginDetails.RoleID == 1 || $scope.userLoginDetails.RoleID == 43) {
                                angular.forEach($scope.MultiselectDoctorlist, function (citem, $index) {
                                    if (doctorInfo.doctordata.User[0].DoctorID == citem.DoctorID) {
                                        citem.isChecked = true;
                                        $scope.selectedDoctors = citem.SecondUserFullName + '-' + citem.NPI;
                                        $scope.AllDoctorsObj.AllDoctorCheck = false;
                                    } else {
                                        citem.isChecked = false;
                                    }

                                });
                            }
                        }
                    }
                }
                if ($scope.Calendardoctorlist1.length > 0) {
                    angular.forEach($scope.Calendardoctorlist1, function (citem, $index) {
                        citem.id = citem.DoctorID;
                        citem.DoctorID = citem.DoctorID;
                        citem.title = citem.SecondUserFullName;
                    });

                    $scope.doctorslist.SearchText = "";
                    var checkedArray = _.where($scope.Calendardoctorlist1, { isChecked: true });
                    checkedArray = checkedArray || [];
                    $scope.mainCalendarView.AllDoctorscheck = false;

                    if (checkedArray.length === $scope.Calendardoctorlist1.length) {
                        $scope.mainCalendarView.AllDoctorscheck = true;
                    }
                }

            } else {
                alertify.error("No Users Found in Selected Departments");
                $scope.MultiselectDoctorlist = [];
                $scope.selectedDoctors = "";

            }
            
            $scope.SearchObj.ConsultationDt = moment(new Date(), 'MM-DD-YYYY').format('YYYY-MM-DD') || ''
            angular.forEach($scope.AppointmentStatusArray, function (kitem) {
                kitem.IsChecked = true;
                if (kitem.AppointmentStatusId === 5 || kitem.AppointmentStatusId === 8 || kitem.AppointmentStatusId === 9 || kitem.AppointmentStatusId === 10) {
                    kitem.IsChecked = false;
                }
            });
            var AppointmentStatuscheckedArray = _.where($scope.AppointmentStatusArray, { IsChecked: true });
            $scope.StatusListObj.AllStatusCheck = AppointmentStatuscheckedArray.length > 0 && $scope.AppointmentStatusArray.length === AppointmentStatuscheckedArray.length ? true : false;
            if ($scope.StatusListObj.AllStatusCheck) {
                $scope.StatusListObj.SelectStatusString = 'All';
            }

            if (!$scope.StatusListObj.AllStatusCheck && AppointmentStatuscheckedArray.length > 0) {
                $scope.StatusListObj.SelectStatusString = 'Selected';
            }
            angular.forEach($scope.BookingTypesArray, function (kitem) {
                kitem.IsChecked = true;
            });
            $scope.BookedTypeObj.AllStatusCheck = true;
            $scope.BookedTypeObj.SelectStatusString = 'All';
            angular.forEach($scope.BookedstatusFilterList, function (Mainitem) {
                Mainitem.IsChecked = true;
            });
            $scope.BookedStatusListObj.AllStatusCheck = true;
            $scope.BookedStatusListObj.SelectStatusString = 'All';
            angular.forEach($scope.ProfileStatusList, function (Mainitem) {
                Mainitem.IsChecked = true;
            });
            $scope.ProfileStatusListObj.AllStatusCheck = true;
            $scope.ProfileStatusListObj.SelectStatusString = 'All';
            angular.forEach($scope.PatientTagList, function (item) {
                item.IsChecked = false;
            });

            var checkedArrayList = [];
            if ($scope.MultiselectDoctorlist.length > 0) {
                checkedArrayList = _.where($scope.MultiselectDoctorlist, { isChecked: true });
            }
            var checkedPatientTagList = [];
            if ($scope.PatientTagList.length > 0) {
                checkedPatientTagList = _.where($scope.PatientTagList, { IsChecked: true });
            }
            var checkedProfileStatusList = [];
            if ($scope.ProfileStatusList.length > 0) {
                checkedProfileStatusList = _.where($scope.ProfileStatusList, { IsChecked: true });
            }
            var checkedBookedstatusFilterList = [];
            if ($scope.BookedstatusFilterList.length > 0) {
                checkedBookedstatusFilterList = _.where($scope.BookedstatusFilterList, { IsChecked: true });
            }
            var checkedAppointmentStatusArray = [];
            if ($scope.AppointmentStatusArray.length > 0) {
                checkedAppointmentStatusArray = _.where($scope.AppointmentStatusArray, { IsChecked: true });
            }
            var checkedBookingTypesArray = [];
            if ($scope.BookingTypesArray.length > 0) {
                checkedBookingTypesArray = _.where($scope.BookingTypesArray, { IsChecked: true });
            }
            var checkedVisitreasons = [];
            if ($scope.Visitreasons.length > 0) {
                checkedVisitreasons = _.where($scope.Visitreasons, { isChecked: true });
            }
            var checkedAppointmentStatusFilterArray = [];
            if ($scope.AppointmentStatusFilterArray.length > 0) {
                checkedAppointmentStatusFilterArray = _.where($scope.AppointmentStatusFilterArray, { isChecked: true });
            }

            var checkedLocationList = [];
            $scope.AppListdoctoraddress = $scope.AppListdoctoraddress || [];
            if ($scope.AppListdoctoraddress.length > 0) {
                checkedLocationList = _.where($scope.AppListdoctoraddress, { IsChecked: true });
            }


            var cacheobj = {
                "SelectedDoctorsList": checkedArrayList || [],
                "OPFromDate": $filter('date')(new Date(), "MM-dd-yyyy") || '',
                "PatientTagList": checkedPatientTagList || [],
                "ProfileStatusList": checkedProfileStatusList || [],
                "BookedstatusFilterList": checkedBookedstatusFilterList || [],
                "AppointmentStatusArray": checkedAppointmentStatusArray || [],
                "BookingTypesArray": checkedBookingTypesArray || [],
                "Visitreasons": checkedVisitreasons || [],
                "AppointmentStatusFilterArray": checkedAppointmentStatusFilterArray ||[],
                "Subtab": 0,
                "RoomTypeId": 0,
                "SelectedLocationList": checkedLocationList || [],
            };
            eHnoteMasterDataService.addSelectedPreAdminList(cacheobj);

            $scope.TagPatientObj.AllPatientTagsCheck = false;
            $scope.ASCDynamicStatusTabs.Subtab = 1;
            $scope.NavObj.IsApptSelectedInfoInd = false;
            $scope.cacheStorageItem.AppointmentId = 0;
            $scope.GetASCDynamicStatusCounts();
            $scope.GetAllAscAppointmentsList(0);
        });

    }
