                if ($scope.TagPatientObj1.AllPatientTagsCheck) {
                    $scope.TagPatientObj1.SelectTag = 'All';
                }

                if (!$scope.TagPatientObj1.AllPatientTagsCheck && checkedArray.length > 0) {
                    $scope.TagPatientObj1.SelectTag = 'Selected';
                } else if (checkedArray.length == 0) {
                    $scope.TagPatientObj1.SelectTag = 'Select Tag Patient';
                }
