            $scope.BreakEventObj.infoobj = tempObj;
            $scope.BreakEventObj.date = tempObj.SlotInfo.ConsultationDate;
            $scope.BreakEventObj.BreakReason = tempObj.SlotInfo.ReasonforBlockSlot || "";
