    function syncLocationTicks() {
        var locationList = $scope.AppListdoctoraddress || [];
        var allLocationsRow = _.find(locationList, function (b) { return b.ClinicId === 0; });
        var branchRows = locationList.filter(function (b) { return b.ClinicId !== 0; });
        var noneChecked = !locationList.some(function (b) { return b.IsChecked; });
        if (noneChecked || (allLocationsRow && allLocationsRow.IsChecked)) {
            angular.forEach(locationList, function (b) { b.IsChecked = true; });
        } else if (allLocationsRow && branchRows.length && branchRows.every(function (b) { return b.IsChecked; })) {
            allLocationsRow.IsChecked = true;
        }
        updateLocationString();
    }

    function updateLocationString() {
        const selectedLocations =$scope.AppListdoctoraddress.filter(mitem => mitem.IsChecked && mitem.ClinicId !== 0);

        if (selectedLocations.length === 0) {
            $scope.LocationTypeObj.SelectLocationString = "Select Location";
        } else if (selectedLocations.length === 1) {
            $scope.LocationTypeObj.SelectLocationString = selectedLocations[0].ClinicName;
        } else if (selectedLocations.length === $scope.AppListdoctoraddress.length - 1) {  // Exclude "All Locations"
            $scope.LocationTypeObj.SelectLocationString = "All Locations";
        } else {
            $scope.LocationTypeObj.SelectLocationString = "Selected Locations";
        }
    }
